import json

def find_shapes(grid, bg_color=3):
    shapes = []
    visited = set()
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != bg_color and (r,c) not in visited:
                shape_color = grid[r][c]
                shape_cells = []
                for dr in range(-1, len(grid)):
                    for dc in range(-1, len(grid[0])):
                        rr, cc = r+dr, c+dc
                        if 0 <= rr < len(grid) and 0 <= cc < len(grid[0]):
                            if grid[rr][cc] == shape_color:
                                shape_cells.append((rr, cc))
                                visited.add((rr, cc))
                shapes.append((shape_color, set(shape_cells)))
    return shapes

shapes = find_shapes(grid, bg_color=3)
print("Shapes found:")
for color, cells in shapes:
    print(f"  Color {color}: {len(cells)} cells")

# Analyze each shape
for color, cells in shapes:
    rows = [c[0] for c in cells]
    cols = [c[1] for c in cells]
    min_r, max_r = min(rows), max(rows)
    min_c, max_c = min(cols), max(cols)
    print(f"\nColor {color}: bounding box ({min_r},{min_c}) to ({max_r},{max_c})")

    height = max_r - min_r + 1
    width = max_c - min_c + 1
    print(f"  Size: {height}x{width}")

    # Check if hollow
    has_interior = False
    for r in range(min_r + 1, max_r):
        for c in range(min_c + 1, max_c):
            if grid[r][c] == bg_color:
                has_interior = True
                break
        if has_interior: break

    print(f"  Hollow: {has_interior}")
    # Fill interior
    filled_cells = cells.copy()
    for r in range(min_r + 1, max_r):
        for c in range(min_c + 1, max_c):
            filled_cells.add((r,c))
    print(f"  Filled size: {len(filled_cells)}")

